"""Record GPU movement, CPU submission, linked pipeline and local chat checks."""
from datetime import datetime,timezone
import json,subprocess,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def save(p,v):p.write_text(json.dumps(v,indent=2)+'\n')

def main():
    now=datetime.now(timezone.utc).isoformat()
    gpu=read(ROOT/'verification/biwn-movement-matrix-checks.json');cpu=read(ROOT/'verification/biwn-movement-submit-checks.json');pipeline=read(ROOT/'verification/biwn-world-movement-pipeline-checks.json');roles=read(ROOT/'verification/biwn-movement-local-review.json')
    assert gpu['GPU_cases']==1025 and gpu['direct_PC_instruction_count']==345 and gpu['mandatory_delay_instruction_count']==8 and gpu['host_guard_cases']==10
    assert cpu['CPU_cases']==256 and cpu['host_guards']==9 and pipeline['cases']==256 and pipeline['redraw_cases']==166
    assert roles['status']=='coordinator_reviewed_correlated_raw_fraction_error_rejected'
    for report in [gpu,cpu]:
        for name,digest in report['source_sha256'].items():assert hashlib.sha256((ROOT/'projects/black-ice-white-noise/restoration'/name).read_bytes()).hexdigest()==digest
    path=ROOT/'verification/easy-movement/20261013T072944.647846Z/protocol.json';ease=read(path);assert ease['status']=='completed_pending_coordinator_review'
    rows=[]
    for i,q in enumerate(ease['questions']):
        calls=[b['toolCallRequest']for e in q['events']if e['role']=='assistant'for b in e['content']if b['type']=='toolCallRequest']
        answer='\n'.join(b['text']for e in q['events']if e['role']=='assistant'for b in e['content']if b['type']=='text').strip()
        assert len(calls)==1 and calls[0]['name']=='project_evidence' and calls[0]['arguments']=={'topic':'world_update'if i==0 else'movement_matrix'}
        assert len(answer.split())<=[60,50,30][i]
        rows.append({'question':q['user'],'answer':answer,'seconds':q['SDK_reported_seconds'],'tool_calls':calls,'verdict':'matches current linked evidence and scope'})
    assert 'Seven helper boundaries remain scripted'in rows[0]['answer'] and '0xC000'in rows[1]['answer'] and 'angle2, then angle1, then angle3'in rows[2]['answer']
    review={'recorded_at':now,'status':'three_plain_movement_questions_passed','directory':str(path.parent),'questions':rows,'scope':'Local SDK tool choice and factual responses with workbench evidence; fresh installed MCP checked separately. Not native LM Studio Chat display/adoption.'}
    save(path.parent/'coordinator-review.json',review);save(ROOT/'verification/easy-movement-review.json',review)
    s=Path(read(ROOT/'projects/black-ice-white-noise/analysis/current-session.json')['directory']);validation=read(s/'boot-slice-validation.json');assert validation['portable_C_component_count']==24
    validation['latest_aggregate_update']=now;save(s/'boot-slice-validation.json',validation)
    models=json.loads(subprocess.check_output([str(Path.home()/'.lmstudio/bin/lms'),'ps','--json'],cwd=Path.home()/'.lmstudio',text=True));assert len(models)==1 and models[0]['identifier']=='advertising-scholar' and models[0]['status']=='idle' and models[0]['contextLength']==32768
    game=('24 checked C components (22 CPU, two GPU). Added CPU E220 submission and GPU4320 matrix/movement algorithm. GPU1016byte overlay matches C in1,025cases:768single-axis byte angles,256mixed/full-width cases and one actual snapshot argument set;10host guards. '
          'CPU submission matches256scripted-device cases/nineguards. Connected CPU update, actual movement generation and C inventory rendering match256originalCPU/GPU comparisons, including166redraws. '
          'Rebuilt path executes zero originalCPU/GPU instructions and no complete gameframes. Seven other polling/input/collision/terrain/scene/entity helpers remain scripted. Existing pinned emulated blitter and synchronous dispatcher model remain dependencies. Full scene/main-loop integration, audio, complete game and physical hardware validation remain unfinished.')
    frontend=('Installed movement_matrix/world_update evidence and updated Game Assistant routing. Three ordinary local questions answered current linkage, raw0xC000fraction/caller-mask0 and angle2→angle1→angle3 correctly in6.5–9.2seconds, one evidence call each. '
              'Native Chat adoption/display remains unverified while locked. API exchanges are logged separately; bounded inventory PNG/actions tool remains installed.')
    quality=('Local Analyst8.40seconds and Reviewer8.30seconds both wrongly said raw negative-unit Zfraction65535; originalGPU/C stores49152(0xC000). Other eight typed fields match scoped evidence. Reviewer copied analyst verbatim; correlated roles are not independent verification. No model code accepted, weight training or default model promotion this turn.')
    pending=('Reconstruct/connect remaining collision, terrain, input/polling and scene/entity helpers, then compare broader world behavior and investigate audio. Continue local-model quality work and verify native Chat adoption when accessible. Advertising Source Pilot v1 remains loadable/experimental; everyday base default. Future256GB hardware unbenchmarked. Full goal active incomplete.')
    evidence=['verification/biwn-movement-matrix-checks.json','verification/biwn-movement-submit-checks.json','verification/biwn-world-movement-pipeline-checks.json','verification/movement-matrix-checked-examples.json','verification/biwn-movement-local-review.json','verification/movement-MCP-check.json','verification/easy-movement-review.json']
    for name in ['setup-status.json','current-runtime-state.json','everyday-inference.json','requirements-audit.json']:
        p=ROOT/'verification'/name;d=read(p)
        if name=='setup-status.json':d.update(updated_at_utc=now,game_work=game,frontend=frontend,pending=pending,latest_movement_model_quality=quality)
        elif name=='current-runtime-state.json':d.update(recorded_at=now,models=models,model_state_refreshed_at=now,decomp_progress=game,visible_chat=frontend,MCP_updated_evidence=frontend,
            local_inference_jobs='Two local review roles and three evidence-assisted movement requests terminal; raw-fraction error rejected. Usual27B idle. No background training/inference claimed.',
            emulator_jobs='GPU1025cases/10guards,CPU submission256cases/9guards,connected256cases and four signed examples terminal. Early observer/alias harness failures retained. Pinned core and old render libraries unchanged.',latest_API_ease_review=str(ROOT/evidence[-1]))
        elif name=='everyday-inference.json':d.update(updated_at=now,model=models,model_state_refreshed_at=now,frontend=frontend,latest_API_ease_review=str(ROOT/evidence[-1]),latest_local_game_roles=str(ROOT/evidence[4]))
        else:
            d.update(recorded_at_utc=now,previous_goal_turn_classification=d['this_goal_turn_classification'],this_goal_turn_classification='progress: GPU4320high-levelC1025cases;CPU E220256cases;linked fullCPUcaller/movement/inventory256cases;three plain local questions pass;correlated raw-fraction drafts rejected',next_safe_work=pending)
            for item in d['requirements']:
                if 'decompilation test'in item['requirement']:item['state']=game;item['evidence']=list(dict.fromkeys(item['evidence']+evidence))
                elif 'Configure LM frontend'in item['requirement']:item['state']=frontend;item['evidence']=list(dict.fromkeys(item['evidence']+evidence[-2:]))
                elif 'Multiagent game'in item['requirement']:item['state']+=' Latest movement roles both misread rawfraction as65535instead49152; originalGPU/C example rejects that field, other eight typed fields match.';item['evidence']=list(dict.fromkeys(item['evidence']+[evidence[4]]))
            d['post_review_evidence'].update({Path(e).name:str(ROOT/e)for e in evidence})
        save(p,d)
    config=read(ROOT/'config.json');config['chat_frontend']['game']['status']=game+' '+frontend;save(ROOT/'config.json',config)
    intake=read(ROOT/'corpus/game/project-intake.json');intake.update(latest_checked_at=now,latest_checked_status=game,latest_movement_pipeline_check=str(ROOT/evidence[2]));save(ROOT/'corpus/game/project-intake.json',intake)
    (ROOT/'CURRENT DECOMPILATION.txt').write_text('BLACK ICE WHITE NOISE — CURRENT RECONSTRUCTION\n\n'+game+'\n\nMOVEMENT SOURCES\n'+str(ROOT/'projects/black-ice-white-noise/restoration/biwn_movement_matrix.c')+'\n'+str(ROOT/'projects/black-ice-white-noise/restoration/biwn_movement_submit.c')+'\nLINKED CHECKS\n'+str(ROOT/evidence[2])+'\n\nGPU CODE/DATA MAPPING\n1016payloadbytes:codeF03240..F0352E,65longword sine tableF03530..F03634, sixpaddingbytes. CPU export has0instructions overlapping4320..4720. GPU coverage:345directly recorded instruction PCs plus eight mandatory branch-delay instructions derived from executed branches/JTRMpage39; not353directly recorded PCs.\n'+str(s/'gpu-movement-overlay/mapping.json')+'\n\nMODEL QUALITY\n'+quality+'\n\nEASY CHAT\n'+frontend+'\n\nLATEST APPROXIMATE CPU EXPORT\n18,306 decoded CPU instructions and206 entry candidates. Automatic C remains approximate. World/primary/secondary/axis names are analyst labels, not recovered original symbols.\n\n'+pending+'\n')
    p=ROOT/'START HERE.txt';text=p.read_text();start=text.index('CURRENT GAME RESULT\n');end=text.index('\nTRY IN ADVERTISING ASSISTANT',start);text=text[:start]+'CURRENT GAME RESULT\n'+game+'\n\n'+frontend+'\n'+text[end:]
    text=text.replace('TRY IN GAME ASSISTANT\n','TRY IN GAME ASSISTANT\nIs GPU movement still scripted in the reconstructed CPU update caller? What remains unfinished?\nFor zero angles, zero translation and speed word0xffff, what raw Zfraction word is stored, and what does the caller use after its14bit mask?\n')
    text+='\nMOVEMENT REVIEW — '+now+'\n'+quality+'\n';p.write_text(text)
    p=ROOT/'projects/black-ice-white-noise/restoration/READ ME.txt';p.write_text(p.read_text()+'\nGPU MOVEMENT / CONNECTED UPDATE — '+now+'\n'+game+'\nReproduce:.venv/bin/python scripts/check_biwn_movement_matrix.py, check_biwn_movement_submit.py, check_biwn_world_movement_pipeline.py. Source biwn_movement_matrix.c/.h and biwn_movement_submit.c/.h. Existing pinned core/old libraries unchanged. OriginalGPU bridge snapshot preserved in isolated check directory; integrated bridge has its own recorded hash.\n')
    p=ROOT/'POST REVIEW.txt';p.write_text(p.read_text()+'\nGPU4320 MOVEMENT AND CONNECTED CPU UPDATE — '+now+'\n'+game+'\nWHO DID WHAT: Codex mapped CPU4320header to1016GPUbytes, classified353instructions/65tablewords/sixpaddingbytes; no existingCPUinstruction overlaps. Read originalAtariJTRMPDF pages39/47/50/51/55 for branchdelay, signed-bottom16IMULT, alternate-register moves and arithmetic shifts. Codex wrote high-level C matrix/rotation/translation algorithm using exact original65coefficients and modular integer arithmetic, plusCPU E220mailbox helper, and compared preservedGPU vsC1025cases and originalCPUhelper256cases. Full2MBRAM, externalRAM readshapes/writevalues,12matrix/translation registers,threealternate-bank rawproducts andfinaldelaypointer match. Readwatchvalues remainzero placeholders. GPUproof uses alignedRAM and fixedtable, not arbitrary aliasing/hardware.\nFirstGPU20case preflight passed; two full runs had1025value comparisons/10guards pass but coverageobserver failed: initially wrong processor selector, then branch-delay PCs absent from history. Fixed observer selection and explicitly derived eight mandatorydelay instructions from recorded branches/JTRMpage39. Final353coverage=345direct+8mandatorydelay, not353directobservations. No C math changes. Earlier fixtures/binaries/statuses retained. CPUhelper script first had else-keyword spacing SyntaxError before execution; repaired and256cases/nineguards pass.\nCodex connected movement CPU/GPU code and prior inventory code into fullCPUcaller test withsevenremainingRTSstub helpers. Firstpreflight used mutable scriptRAM as commonstartingstate; original helpereffects leaked intoCseed. Retainedmismatch, fixed harness tofreeze initialbytes. Eightcase preflight then256case run/166redraws pass without restoredCsource changes. Original path runs actualE220anddrawing/text/sprite CPU code plus original4320/4B00GPUoverlays; Cpath runscompiledC with0originalCPU/GPUinstructions,0completegameframes. Four additional signedmovement examples matchGPU/C; identityspeed-1stores integerZffff/rawfractionc000/callermaskedfraction0.\n'+quality+'\nExact local role prompts/responses:\n'+str(Path(roles['directory'])/'prompts-and-responses.txt')+'\nCoordinator role audit:\n'+str(ROOT/evidence[4])+'\nThree normal questions used one evidencecall each and correctly returned currentlinkage, rawfraction49152/0xC000withmasked0, androtationorderangle2→angle1→angle3. SDKworkbenchtool code; freshinstalledMCP separatelychecked. NativeChat stilllocked on freshUIcheck, no unlockrequest peruserdirection.\nExact plain prompts/responses:\n'+str(path.parent/'prompts-and-responses.txt')+'\nCoordinator audit:\n'+str(ROOT/evidence[-1])+'\nMapping and primarymanual:\n'+str(s/'gpu-movement-overlay/mapping.json')+'\n'+str(ROOT/'tools/jaguar-technical-manual/original-JTRM-rev8.pdf')+'\n'+pending+'\n')
    subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'scripts/install_chat_runtime.py')],check=True)
    save(ROOT/'verification/movement-checkpoint.json',{'recorded_at':now,'backup':read(ROOT/'verification/movement-checkpoint-backup.json')['directory'],'components':24,'CPU_components':22,'GPU_components':2,'GPU_matrix_cases':1025,'CPU_submit_cases':256,'connected_cases':256,'connected_redraw_cases':166,'extra_signed_examples':4,'GPU_coverage':{'direct':345,'mandatory_delay':8},'plain_chat_questions_passed':3,'known_compute_jobs':'terminal','models':models,'full_goal_status':'active incomplete','evidence':evidence,'native_Chat_adoption':'unverified while locked','next_work':pending})
    print(json.dumps({'components':24,'GPU_cases':1025,'CPU_submit_cases':256,'connected_cases':256,'plain_chat_questions':3,'installed':True}))

if __name__=='__main__':main()
